tests:
try:
    get_key({})
    raise AssertionError('should raise RuntimeError')
except RuntimeError as e:
    assert 'ANTHROPIC_API_KEY' in str(e), 'the message should name the variable'

try:
    get_key({'ANTHROPIC_API_KEY': ''})
    raise AssertionError('empty should raise')
except RuntimeError:
    pass

ex.sol:
def get_key(env):
    key = env.get('ANTHROPIC_API_KEY')
    if not key:
        raise RuntimeError('Set ANTHROPIC_API_KEY in your .env file')
    return key
